const templates={news:'Xin chào quý vị và các bạn. Chào mừng đến với bản tin hôm nay.\n\nCùng Quân Voice Studio điểm qua những thông tin đáng chú ý, được kể bằng giọng nói của chính bạn.',story:'Có những câu chuyện bắt đầu từ một điều rất nhỏ. Một buổi sáng bình yên, một tách cà phê ấm, và một lời chào đã lâu chưa nói.\n\nHôm nay, tôi muốn kể bạn nghe câu chuyện ấy.',product:'Mỗi ý tưởng hay đều xứng đáng được lắng nghe. Biến những dòng chữ thành giọng nói tự nhiên, mang dấu ấn riêng của bạn.\n\nBắt đầu câu chuyện của bạn cùng Quân Voice Studio.'};
let draft;try{draft=JSON.parse(localStorage.getItem('qv-draft')||'{}')}catch{draft={}}
let S={engines:[],connected:false,view:'studio',engine:draft.engine||'vieneu',language:draft.language||'vi',text:draft.text??templates.news,preset:draft.preset||'Hải Đăng',voice:draft.voice||'',speed:draft.speed||1,format:draft.format||'wav',emotion:draft.emotion??.5,autoEmotion:false,batch:false,voices:[],jobs:[],banks:{},cloneEngine:draft.cloneEngine||'vieneu',cloneForm:{name:'',language:'vi',transcript:'',consent:false,outputLanguage:'vi',sampleText:''},previews:{},previewTexts:{},libraryTab:'builtin',libraryModel:'vieneu',libraryVariant:'v3turbo',presetSearch:'',filter:'all',search:'',status:{}};
let selectedFile=null,fileURL=null,recorder=null,recordStream=null,recordTimer=null,busy=false,toastTimer;
let draftStorageWarned=false,preferenceTimer=null;
function saveDraft(){S.localChanged=true;queuePreferences();try{localStorage.setItem('qv-draft',JSON.stringify({engine:S.engine,language:S.language,text:S.text,preset:S.preset,voice:S.voice,speed:S.speed,format:S.format,emotion:S.emotion,cloneEngine:S.cloneEngine,vieneuVariant:S.engines.find(e=>e.id==='vieneu')?.config?.variant||'v3turbo'}));draftStorageWarned=false}catch{if(!draftStorageWarned){draftStorageWarned=true;toast('Bộ nhớ trình duyệt đã đầy. Nội dung vẫn trên màn hình và được lưu khi kết nối bộ xử lý; bấm Lưu dự án để có thêm file JSON.')}}}
function preferenceSnapshot(includeText=true){return {engine:S.engine,language:S.language,voice:S.voice,preset:S.preset,...(includeText?{text:S.text}:{}),speed:S.speed,format:S.format,emotion:S.emotion,cloneEngine:S.cloneEngine,warm_on_start:S.startPrefs?.warm_on_start!==false,cached_only:S.startPrefs?.cached_only!==false,theme:window.QVTheme?.get?.()||{}}}
function queuePreferences(){if(!S.connected||!S.prefsLoaded)return;clearTimeout(preferenceTimer);preferenceTimer=setTimeout(()=>api('/preferences',{method:'PUT',body:JSON.stringify(preferenceSnapshot())}).catch(()=>{}),450)}
async function restorePreferences(){const p=await api('/preferences');S.startPrefs=p;if(!S.localChanged&&(p.has_saved!==false||Object.keys(draft).length===0)){const e=S.engines.find(e=>e.id===p.engine&&e.kind==='tts');if(e){S.engine=e.id;S.language=e.languages.includes(p.language)?p.language:e.languages[0]}if(typeof p.text==='string')S.text=p.text;if(typeof p.preset==='string')S.preset=p.preset;if(typeof p.voice==='string')S.voice=S.voices.some(v=>v.id===p.voice)?p.voice:'';if(typeof p.speed==='number')S.speed=p.speed;if(p.format)S.format=p.format;if(typeof p.emotion==='number')S.emotion=p.emotion;if(p.cloneEngine)S.cloneEngine=p.cloneEngine;if(p.theme&&Object.keys(p.theme).length)window.QVTheme?.set?.(p.theme)}S.prefsLoaded=true;ensurePreset();queuePreferences()}
function runtimePanel(){if(!S.connected)return '<section class="runtime-card"><div><strong>Mở bản Desktop để dùng giọng đã lưu</strong><p>Ứng dụng trên máy giữ model, giọng tham chiếu và cấu hình cho những lần mở sau.</p></div><button class="button small" data-action="guide">Cài bản Desktop</button></section>';const r=S.status.runtime||{},name=S.engines.find(e=>e.id===r.engine)?.name||'Mô hình';const loading=['loading','running'].includes(r.state);return `<section class="runtime-card"><div><strong>${r.loaded?`${esc(name)} đang được giữ sẵn trong RAM`:loading?`Đang nạp ${esc(name)} từ ổ đĩa…`:'Giọng và dữ liệu mô hình đã lưu trên máy'}</strong><p>${r.loaded?'Nghe thử và tạo tiếp bằng model này sẽ dùng lại bộ xử lý.':'Lần mở mới chỉ cần nạp vào RAM; không cài hoặc tải lại model đã chuẩn bị.'}</p>${r.error||r.warm_error?`<p class="error">${esc((r.error||r.warm_error).slice(-350))}</p>`:''}</div><div class="runtime-actions"><button class="button small" data-action="warm-current" ${!S.connected||loading?'disabled':''}>${icon('play')}Chuẩn bị giọng đang chọn</button><button class="text-button" data-action="release-runtime" ${!r.loaded||loading?'disabled':''}>Giải phóng RAM</button></div></section>`}
window.addEventListener('qv-appearance',queuePreferences);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(path,options={}){const res=await fetch('/api'+path,{...options,signal:options.signal||AbortSignal.timeout(15000),headers:{...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}});if(!res.ok){let data;try{data=await res.json()}catch{data={detail:'Không kết nối được bộ xử lý.'}}throw new Error(typeof data.detail==='string'?data.detail:'Dữ liệu chưa hợp lệ. Kiểm tra các trường nhập.')}return res.json();}
function engine(){return S.engines.find(e=>e.id===S.engine)||S.engines[0]}
function voiceOptions(includeDefault=true){return `${includeDefault?'<option value="">Giọng có sẵn của mô hình</option>':''}`+S.voices.filter(v=>v.kind!=='source').map(v=>`<option value="${esc(v.id)}" ${S.voice===v.id?'selected':''}>${esc(v.name)} · ${v.duration}s</option>`).join('')}
function header(title,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">QUÂN VOICE / STUDIO</div><h1>${title}</h1><p>${sub}</p></div><div class="title-actions">${actions}</div></div>`}
function statusText(e){if(!S.connected)return 'Chưa kết nối';if(e.setup?.state==='failed')return 'Cài chưa xong · Thử lại';if(e.setup?.state==='cancelled')return 'Đã dừng cài';return ({preparing:'Đang chuẩn bị',ready:'Đã chuẩn bị mô hình',service_standby:'API tự mở khi sử dụng',not_installed:'Chưa cài đặt',dependencies:'Đã cài thư viện',needs_weights:'Cần trọng số',service_ready:'API đang chạy',service_offline:'API chưa chạy'})[e.state]||'Chưa cài đặt'}
function waveBars(cls='wave-empty'){return `<div class="${cls}" aria-hidden="true">${Array.from({length:31},(_,i)=>`<i style="height:${6+Math.sin(i*1.7)**2*20}px"></i>`).join('')}</div>`}
function render(){
 const root=$('#main-content');ensurePreset();$('#breadcrumb').textContent=labels[S.view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===S.view));$('#voice-count').textContent=S.voices.filter(v=>v.kind!=='source').length+Object.values(S.banks).reduce((n,b)=>n+(b.voices?.length||0),0);
 root.innerHTML=({studio:studio,clone:clone,transcribe:transcribe,voices:voices,models:models,history:history,settings:settings}[S.view]||studio)();hydrate(root);bindView();
}
function studio(){const e=engine();if(!e)return '';const selectedVoice=S.voices.find(v=>v.id===S.voice);return `${header('Mỗi giọng nói, một dấu ấn riêng.','Biến ý tưởng của bạn thành giọng đọc tự nhiên, giàu cảm xúc.',`<button class="button ghost" data-action="guide">${icon('book')}Hướng dẫn</button><button class="button" data-action="export-txt">${icon('text')}Xuất TXT</button><button class="button" data-action="export-srt">${icon('download')}Xuất SRT</button><button class="button" data-action="export-draft">${icon('download')}Lưu dự án</button>`)}
<div id="runtime-status">${runtimePanel()}</div><section class="intro"><div class="intro-copy"><div class="intro-label">${icon('spark')} KHÔNG GIAN SÁNG TẠO GIỌNG NÓI</div><h2>Câu chuyện của bạn. Giọng nói của bạn.</h2><p>Viết nội dung, chọn giọng đọc và để AI kể câu chuyện theo cách của bạn.</p></div><div class="intro-art" aria-hidden="true">${Array.from({length:25},(_,i)=>`<span style="height:${10+Math.sin(i*.8)**2*58}px;opacity:${.4+Math.sin(i)**2*.5}"></span>`).join('')}</div></section>
<div class="studio-layout"><div><section class="card editor"><div class="editor-top"><div class="card-title">${icon('text')}Nội dung của bạn</div><button class="text-button" data-action="import-text">${icon('upload')} Nhập file .txt</button></div><div class="editor-tabs"><button data-mode="single" class="${!S.batch?'selected':''}">Văn bản</button><button data-mode="batch" class="${S.batch?'selected':''}">Tạo theo đoạn <span class="tiny-label">BATCH</span></button></div><div class="editor-area"><textarea id="script" class="script" aria-label="Nội dung cần tạo giọng" spellcheck="false" placeholder="Viết câu chuyện bạn muốn kể ở đây…">${esc(S.text)}</textarea></div><div class="editor-bottom"><span id="script-count"></span><div class="editor-tools"><button data-action="clear-text">${icon('trash')}Xóa</button><button data-action="normalize-text">${icon('spark')}Chuẩn hóa khoảng trắng</button></div></div><div class="preset-row"><span>Bắt đầu với mẫu:</span><button class="chip" data-template="news">Bản tin</button><button class="chip" data-template="story">Kể chuyện</button><button class="chip" data-template="product">Giới thiệu sản phẩm</button></div></section>
<div class="under-editor">${icon('help')}<span>${S.batch?'Mỗi đoạn cách nhau bằng một dòng trống sẽ được tạo thành một file riêng.':'Mẹo nhỏ: Dấu phẩy và dấu chấm giúp giọng đọc ngắt nghỉ tự nhiên hơn.'}</span></div><section class="card result-card"><div class="card-heading"><div class="card-title">${icon('headphones')}Kết quả của bạn</div><button class="text-button" data-view="history">Xem tất cả ${icon('arrow-right')}</button></div><div id="recent-result">${resultPanel()}</div></section><div class="section-caption">Khám phá các mô hình <button class="text-button" data-view="models">Tất cả 7 mô hình ${icon('arrow-right')}</button></div><div class="model-strip">${S.engines.filter(x=>x.kind==='tts').slice(0,6).map(m=>`<button class="mini-model ${m.id===S.engine?'selected':''}" data-engine="${m.id}"><span class="model-letter" style="color:${m.color}">${m.name.slice(0,1)}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.by)}</small></div>${m.id===S.engine?'<span class="check">✓</span>':''}</button>`).join('')}</div></div>
<aside><section class="card model-settings"><div class="card-heading"><div class="card-title">${icon('sliders')}Thiết lập giọng đọc</div><span>TÙY CHỈNH</span></div><div class="settings-body"><div class="field"><label>Mô hình AI <small>6 mô hình tạo giọng</small></label><button class="model-select" data-action="pick-engine"><span class="model-letter">${e.name.charAt(0)}</span><div><strong>${esc(e.name)}</strong><small>${esc(e.by)} · ${e.clone?'Có thể clone giọng':'Giọng preset'}</small></div>${icon('chevron')}</button><div class="recommended">${icon('spark')}${S.engine==='vieneu'?'Đề xuất cho nội dung tiếng Việt':statusText(e)}</div></div><div class="field"><label for="language">Ngôn ngữ <small>Theo khả năng mô hình</small></label><select id="language" class="select-control">${e.languages.map(l=>`<option value="${l}" ${l===S.language?'selected':''}>${esc(languageNames[l]||l)}</option>`).join('')}</select></div><div class="field"><label for="voice">Giọng đọc <button class="text-button" data-view="voices">${icon('users')}Xem tất cả</button></label><select id="voice" class="select-control">${nativeOptions(e)}</select><div class="voice-picker-hint">${selectedVoice?`Giọng bạn đã lưu: ${esc(selectedVoice.name)}`:esc(selectedNative()?.description||bankFor(S.engine).source)}<br><button class="text-button" data-view="clone">${icon('plus')}Clone mới</button></div></div>${previewPanel('studio')}<div class="settings-divider"></div><div class="field"><label for="speed">Tốc độ đọc <span id="speed-value" class="field-value">${S.speed.toFixed(2)}×</span></label><input type="range" id="speed" min="0.5" max="2" step="0.05" value="${S.speed}"><div class="range-labels"><span>Chậm · 0.5×</span><span>Nhanh · 2×</span></div></div>${['chatterbox','index-tts'].includes(S.engine)?`<div class="field"><label for="emotion">Cường độ cảm xúc <span id="emotion-value" class="field-value">${Math.round(S.emotion*100)}%</span></label><input id="emotion" type="range" min="0" max="1" step="0.05" value="${S.emotion}">${S.engine==='index-tts'?`<label class="consent"><input id="auto-emotion" type="checkbox" ${S.autoEmotion?'checked':''}> Suy luận cảm xúc từ nội dung (tải thêm mô hình)</label>`:''}</div>`:''}<div class="field"><label>Định dạng xuất <small>Âm thanh</small></label><div class="format-switch"><button data-format="wav" class="${S.format==='wav'?'active':''}">WAV <small>· Gốc</small></button><button data-format="mp3" class="${S.format==='mp3'?'active':''}">MP3 <small>· Gọn</small></button></div></div><button class="button primary generate" data-action="generate">${icon('spark')} ${S.batch?'Tạo giọng theo đoạn':'Tạo giọng nói'} ${icon('arrow-right')}</button><p class="generate-foot">${S.connected?'Xử lý trên máy của bạn · Tác vụ chạy lần lượt':'Cần mở bản Windows để tạo âm thanh thực'}</p>${S.engine!=='vieneu'?`<div class="model-note">${esc(e.note)}</div>`:''}</div></section><div class="guide-inline">${icon('monitor')}<div><strong>Studio trên máy tính</strong><p>Cài một lần. Giữ lại dữ liệu mô hình.</p></div><button data-action="guide" aria-label="Cài ứng dụng">${icon('chevron')}</button></div></aside></div>`}
function resultPanel(){const recent=S.jobs.find(j=>j.type==='tts');if(!recent)return `<div class="result-empty">${waveBars()}<strong>Giọng nói của bạn sắp được cất lên</strong><p>Kết quả âm thanh sẽ xuất hiện tại đây sau khi tạo.</p></div>`;return jobRow(recent)}
function clone(){const e=S.engines.find(e=>e.id===S.cloneEngine&&e.clone)||S.engines.find(e=>e.id==='vieneu');S.cloneEngine=e.id;const f=S.cloneForm;if(!e.languages.includes(f.outputLanguage))f.outputLanguage=e.languages[0];return `${header('Clone giọng với mô hình bạn chọn.','Nghe giọng gốc, nghe thử bản clone rồi mới tạo nội dung đầy đủ.',`<button class="button" data-view="voices">${icon('users')}Thư viện giọng</button>`)}<section class="card clone-model-section"><div class="card-title">${icon('layers')}1. Chọn mô hình để clone</div><p class="clone-model-help">Có 7 mô hình trong ứng dụng; 5 mô hình hỗ trợ clone từ file tham chiếu.</p><div class="clone-model-grid">${S.engines.map(m=>`<button type="button" class="clone-model-card ${m.id===S.cloneEngine?'selected':''}" data-clone-engine="${m.id}" aria-pressed="${m.id===S.cloneEngine}" ${!m.clone?'disabled':''}><span class="model-letter" style="color:${m.color}">${m.name.charAt(0)}</span><strong>${esc(m.name)}</strong><span>${m.clone?(m.languages.includes('vi')?'Clone · Có tiếng Việt':'Clone · '+m.languages.slice(0,4).map(l=>l.toUpperCase()).join(' / ')):(m.kind==='asr'?'Chép lời · Không clone':'Preset Realtime · Không clone file')}</span>${m.id===S.cloneEngine?icon('check'):''}</button>`).join('')}</div><div class="clone-current-model"><strong>Đang chọn: ${esc(e.name)}</strong><span>${statusText(e)}</span><button class="text-button" data-config="${e.id}">${icon('settings')}Cấu hình / cài mô hình</button></div></section><div class="two-col clone-workspace"><section class="card form-card"><div class="card-title" style="margin-bottom:22px">${icon('mic')}2. Thêm giọng tham chiếu</div><form id="voice-form"><label class="upload-zone" id="upload-zone" for="audio-input">${icon('upload')}<strong>Kéo thả hoặc chọn file giọng mẫu</strong><p>WAV, MP3, M4A, FLAC, WebM · Tối đa 100 MB<br>Nên dùng đoạn 3–15 giây, một người nói, ít tạp âm.</p><input id="audio-input" class="hidden" type="file" accept="audio/*,.m4a,.flac"></label><div id="file-detail"></div><div style="display:flex;align-items:center;margin:15px 0 23px"><button type="button" class="button small" data-action="record">${icon('mic')}Thu âm trực tiếp</button><span id="record-time" class="record-time"></span></div><div class="field"><label for="voice-name">Tên giọng nói</label><input id="voice-name" class="input-control" required maxlength="120" value="${esc(f.name)}" placeholder="Ví dụ: Giọng Quân · Bản tin"></div><div class="field"><label for="voice-language">Ngôn ngữ trong file gốc</label><select id="voice-language" class="select-control">${['vi','en','zh','ja','ko','yue','fr','de','es','ar','it','pt','ru'].map(l=>`<option value="${l}" ${f.language===l?'selected':''}>${languageNames[l]}</option>`).join('')}</select></div><div class="field"><label for="reference-text">Lời thoại trong giọng mẫu <small>${e.id==='gpt-sovits'?'Bắt buộc với GPT-SoVITS':'Nên nhập nếu mô hình cần'}</small></label><textarea id="reference-text" class="input-control" placeholder="Nhập chính xác những gì được nói trong đoạn thu…">${esc(f.transcript)}</textarea></div><label class="consent"><input id="consent" type="checkbox" ${f.consent?'checked':''} required>Tôi có quyền sử dụng và nhân bản giọng nói trong bản thu này.</label><button class="button primary full-width" type="submit">${icon('plus')}Lưu giọng & dùng ${esc(e.name)}</button></form></section><div><section class="card clone-listen-card"><div class="card-title">${icon('headphones')}3. Nghe thử trước khi tạo</div><p class="clone-model-help">Giọng AI đọc câu ngắn bằng <strong>${esc(e.name)}</strong>. File gốc vẫn có trình phát riêng ở bên trái để bạn so sánh.</p><div class="field"><label for="clone-output-language">Ngôn ngữ nội dung mới</label><select id="clone-output-language" class="select-control">${e.languages.map(l=>`<option value="${l}" ${f.outputLanguage===l?'selected':''}>${languageNames[l]}</option>`).join('')}</select></div>${previewPanel('clone')}<p class="preview-caption">Nghe thử chưa lưu hồ sơ vào thư viện. Khi ưng ý, bấm “Lưu giọng & dùng ${esc(e.name)}” để tạo nội dung dài.</p></section><div class="alert" style="margin-top:18px">${esc(e.note)}<br>Hồ sơ giọng lưu âm thanh tham chiếu để dùng lại; thao tác này không huấn luyện một mô hình mới.</div></div></div>`}
function transcribe(){const source=S.voices.filter(v=>v.kind==='source');return `${header('Từ âm thanh, thành câu chữ.','Whisper chuyển lời nói thành văn bản và phụ đề SRT.',`<button class="button" data-view="history">${icon('clock')}Kết quả chép lời</button>`)}<div class="two-col"><section class="card form-card"><form id="transcribe-form"><div class="card-title" style="margin-bottom:22px">${icon('text')}Nhận dạng giọng nói</div><div class="field"><label for="source-file">Chọn file âm thanh</label><input id="source-file" class="input-control" type="file" accept="audio/*,.m4a,.flac"></div>${source.length?`<div class="field"><label for="source-existing">Hoặc dùng file đã tải</label><select id="source-existing" class="select-control"><option value="">Chọn file đã lưu</option>${source.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label for="asr-lang">Ngôn ngữ</label><select id="asr-lang" class="select-control">${S.engines.find(e=>e.id==='whisper').languages.map(l=>`<option value="${l}">${languageNames[l]}</option>`).join('')}</select></div><div class="alert">${statusText(S.engines.find(e=>e.id==='whisper'))} · Chọn kích thước Whisper trong Kho mô hình. Bản base phù hợp để bắt đầu; máy mạnh có thể dùng small, medium hoặc turbo.</div><button type="submit" class="button primary full-width">${icon('text')}Chuyển thành văn bản</button></form></section><section class="card"><div class="card-heading"><div class="card-title">Bản chép lời mới nhất</div></div>${S.jobs.find(j=>j.type==='asr')?jobRow(S.jobs.find(j=>j.type==='asr')):`<div class="empty-large">${icon('text')}<h3>Lời nói được lưu thành chữ</h3><p>Tải âm thanh lên để bắt đầu. Sau khi xử lý, tải bản TXT hoặc phụ đề SRT tại đây.</p></div>`}</section></div>`}
function uploadedVoices(){const list=S.voices.filter(v=>v.kind!=='source');return `${header('Thư viện giọng của bạn.','Những giọng nói quen thuộc, sẵn sàng cho câu chuyện tiếp theo.',`<button class="button primary" data-view="clone">${icon('plus')}Thêm giọng mới</button>`)}${list.length?`<div class="voice-list">${list.map(v=>`<section class="card voice-tile"><div style="display:flex;justify-content:space-between;align-items:center"><span class="voice-avatar">${icon('mic')}</span><span class="tag">GIỌNG THAM CHIẾU</span></div><h3>${esc(v.name)}</h3><p>${esc(languageNames[v.language]||v.language)} · ${v.duration} giây · ${new Date(v.created*1000).toLocaleDateString('vi-VN')}</p>${v.transcript?`<p>${esc(v.transcript.slice(0,130))}${v.transcript.length>130?'…':''}</p>`:''}<audio controls preload="none" src="/api/voices/${v.id}/audio"></audio><div class="voice-tile-actions"><button class="text-button" data-use-voice="${v.id}">Dùng giọng này ${icon('arrow-right')}</button><button class="icon-button" data-delete-voice="${v.id}" aria-label="Xóa giọng ${esc(v.name)}">${icon('trash')}</button></div></section>`).join('')}</div>`:`<section class="card empty-large">${icon('users')}<h3>Giọng đầu tiên, câu chuyện đầu tiên.</h3><p>Thêm một đoạn thu âm của bạn để lưu hồ sơ giọng nói và sử dụng cho những lần tạo sau.</p><button class="button primary" data-view="clone">${icon('plus')}Thêm giọng đầu tiên</button></section>`}`}

function bankFor(id,variant){const bank=S.banks[id]||{voices:[],default:'',source:'Chưa có danh sách giọng.'};if(id==='vieneu'&&bank.variants){const kind=variant||S.engines.find(e=>e.id===id)?.config?.variant||'v3turbo';return bank.variant===kind?bank:{...bank,...bank.variants[kind==='v3nano'?'v3nano':'v3turbo']}}return bank}
function nativeChoices(){const choices=bankFor(S.engine).voices||[];return S.engine==='vibevoice'?choices.filter(v=>v.language===S.language):choices}
function ensurePreset(){if(!S.engines.length)return;const choices=nativeChoices();if(!choices.some(v=>v.id===S.preset)){const fallback=bankFor(S.engine).default;S.preset=choices.find(v=>v.id===fallback)?.id||choices[0]?.id||''}}
function selectedNative(){return bankFor(S.engine).voices.find(v=>v.id===S.preset)}
function nativeOptions(e){const choices=nativeChoices();return (choices.length?`<optgroup label="${e.id==='index-tts'?'Giọng mẫu của dự án':'Giọng của mô hình'}">${choices.map(v=>`<option value="preset:${esc(v.id)}" ${!S.voice&&S.preset===v.id?'selected':''}>${esc(v.name)}${v.description?' · '+esc(v.description):''}</option>`).join('')}</optgroup>`:`<option value="" ${!S.voice?'selected':''}>${e.id==='fish-speech'?'Không chọn giọng cố định':'Chọn giọng đã lưu bên dưới'}</option>`)+(e.clone&&S.voices.some(v=>v.kind!=='source')?`<optgroup label="Giọng bạn đã lưu">${S.voices.filter(v=>v.kind!=='source').map(v=>`<option value="user:${v.id}" ${S.voice===v.id?'selected':''}>${esc(v.name)} · ${v.duration}s</option>`).join('')}</optgroup>`:'')}
function libraryTabs(){return `<div class="library-tabs"><button data-library-tab="builtin" class="${S.libraryTab==='builtin'?'active':''}">Giọng có sẵn trong mô hình</button><button data-library-tab="uploaded" class="${S.libraryTab==='uploaded'?'active':''}">Giọng bạn đã lưu (${S.voices.filter(v=>v.kind!=='source').length})</button></div>`}
function voices(){if(S.libraryTab==='uploaded'){const html=uploadedVoices();const position=html.indexOf('</div></div>');return html.slice(0,position+12)+libraryTabs()+html.slice(position+12)}const bank=bankFor(S.libraryModel,S.libraryVariant);return `${header('Tìm chất giọng bạn muốn.','Danh sách được lấy từ preset, file mẫu và API thực tế của từng mô hình.',`<button class="button" data-action="refresh-presets">${icon('refresh')}Làm mới danh sách</button><button class="button primary" data-view="clone">${icon('plus')}Thêm giọng</button>`)}${libraryTabs()}<div class="preset-filter"><select id="library-model" class="select-control" aria-label="Lọc theo mô hình">${S.engines.map(e=>`<option value="${e.id}" ${e.id===S.libraryModel?'selected':''}>${e.name}</option>`).join('')}</select>${S.libraryModel==='vieneu'?`<select id="library-variant" class="select-control" aria-label="Phiên bản VieNeu"><option value="v3turbo">v3 Turbo · 25 giọng</option><option value="v3nano" ${S.libraryVariant==='v3nano'?'selected':''}>v3 Nano · 11 giọng</option></select>`:''}<input id="preset-search" class="input-control" aria-label="Tìm giọng" placeholder="Tìm tên giọng, nam/nữ, vùng miền, ngôn ngữ…" value="${esc(S.presetSearch)}"></div><div class="preset-model-info"><strong>${esc(S.engines.find(e=>e.id===S.libraryModel)?.name)} · ${bank.voices.length} lựa chọn</strong><br>${esc(bank.source)}${S.libraryModel==='vibevoice'?`<br><button class="text-button" data-action="download-vibe-presets">${icon('download')}Tải thêm các gói giọng thử nghiệm chính thức</button>`:''}${S.libraryModel==='fish-speech'&&!bank.connected?'<br>Chưa đọc được API cục bộ. Khởi động Fish Speech rồi bấm Làm mới danh sách.':''}</div><div class="voice-list" id="builtin-grid">${builtInCards(bank)}</div>`}
function builtInCards(bank){const query=S.presetSearch.toLocaleLowerCase('vi-VN');const list=bank.voices.filter(v=>[v.name,v.description,languageNames[v.language]||'',v.region,v.gender==='female'?'nữ':v.gender==='male'?'nam':''].join(' ').toLocaleLowerCase('vi-VN').includes(query));return list.length?list.map(v=>`<section class="card voice-tile preset-card"><div style="display:flex;justify-content:space-between;align-items:center"><span class="voice-avatar">${icon('wave')}</span><span class="preset-badge">${v.kind==='sample'?'Mẫu tham chiếu':v.kind==='reference'?'Giọng API':v.kind==='default'?'Theo checkpoint':'Preset'}</span></div><h3>${esc(v.name)}</h3><p>${esc(v.description)}</p><p>${esc(v.language?languageNames[v.language]||v.language:'Theo ngôn ngữ nội dung')} ${v.region?' · '+esc(v.region):''}</p><div class="voice-tile-actions"><button class="text-button" data-native="${esc(v.id)}" data-native-engine="${S.libraryModel}" data-native-variant="${S.libraryVariant}">Dùng giọng này ${icon('arrow-right')}</button><button class="text-button" data-preview-native="${esc(v.id)}" data-native-engine="${S.libraryModel}" data-native-variant="${S.libraryVariant}">${icon('play')}${v.kind==='sample'?'Nghe file mẫu':'Tạo mẫu nghe'}</button></div></section>`).join(''):`<section class="card empty-large" style="grid-column:1/-1">${icon('mic')}<h3>${bank.voices.length?'Không có giọng phù hợp tìm kiếm':'Mô hình này chưa có danh sách preset'}</h3><p>${esc(bank.source)}</p><button class="button" data-view="clone">Thêm giọng tham chiếu</button></section>`}
async function chooseNative(id,engineId,variant){const e=S.engines.find(e=>e.id===engineId);if(!e)return;if(engineId==='vieneu'){if(S.connected&&e.config?.variant!==variant){const updated=await api('/engines/vieneu',{method:'PUT',body:JSON.stringify({...e.config,variant})});Object.assign(e,updated)}e.config={...e.config,variant}}invalidatePreview('studio');S.previewTexts.studio='';S.engine=engineId;S.voice='';const item=bankFor(engineId,variant).voices.find(v=>v.id===id);if(!item)throw new Error('Giọng không còn trong danh sách. Hãy làm mới.');S.preset=id;if(engineId==='vibevoice')S.language=item.language;else if(!e.languages.includes(S.language))S.language=e.languages[0];saveDraft();navigate('studio');return item}
async function previewNative(id,engineId,variant){const bank=bankFor(engineId,variant),item=bank.voices.find(v=>v.id===id);if(!item)return;const e=S.engines.find(e=>e.id===engineId);const language=engineId==='vibevoice'?item.language:e.languages.includes(S.language)?S.language:e.languages[0];invalidatePreview('library');S.libraryPreview={id,engine:engineId,variant,language,name:item.name};modal('Nghe thử · '+esc(item.name),`<p>${esc(e.name)} · ${esc(languageNames[language])}. Nghe câu ngắn trước khi chọn giọng cho nội dung dài.</p>${engineId==='index-tts'&&S.connected?`<div class="raw-sample"><strong>File tham chiếu gốc</strong><audio controls preload="none" style="width:100%" src="/api/engines/index-tts/presets/${encodeURIComponent(id)}/audio"></audio></div>`:''}${previewPanel('library')}`);bindPreview('library');paintPreview('library')}
async function refreshPresets(){if(S.connected)S.banks=await api('/presets');ensurePreset();render();toast(S.connected?'Đã đọc lại danh sách giọng trên máy.':'Đang xem danh sách đi kèm mã nguồn. Mở bản Windows để quét giọng đã cài.')}

const previewTimers={};let previewSequence=0;let previewReference=null;
function sampleText(language){return ({vi:'Xin chào, đây là giọng đọc bạn đang nghe thử trong Quân Voice Studio.',en:'Hello, this is a preview of the selected voice in your studio.',de:'Hallo, dies ist eine Vorschau der ausgewählten Stimme.',fr:'Bonjour, voici un aperçu de la voix sélectionnée.',es:'Hola, esta es una muestra de la voz seleccionada.',it:'Ciao, questa è una prova della voce selezionata.',ja:'こんにちは。これは選択した音声のサンプルです。',ko:'안녕하세요. 선택한 음성의 미리 듣기입니다.',nl:'Hallo, dit is een voorbeeld van de gekozen stem.',pl:'Dzień dobry, to jest próbka wybranego głosu.',pt:'Olá, esta é uma prévia da voz selecionada.',zh:'你好，这是所选声音的试听。',ar:'مرحبًا، هذه عينة من الصوت المختار.'})[language]||'Hello, this is a preview of your selected voice.'}
function previewLanguage(context){return context==='clone'?S.cloneForm.outputLanguage:context==='library'?S.libraryPreview?.language||'en':S.language}
function previewPanel(context){const text=S.previewTexts[context]||sampleText(previewLanguage(context));return `<section class="preview-panel" id="preview-panel-${context}"><label class="label" for="preview-text-${context}">Câu đọc nghe thử <small>Không giới hạn ký tự</small></label><textarea class="input-control preview-script" id="preview-text-${context}" rows="3">${esc(text)}</textarea><div class="preview-actions"><button class="button ${context==='studio'?'':'primary'}" type="button" data-preview-context="${context}" id="preview-start-${context}">${icon('headphones')}Nghe thử ${context==='clone'?'giọng clone':'giọng AI'}</button><button type="button" class="button small hidden" id="preview-cancel-${context}" data-cancel-preview="${context}">${icon('stop')}Hủy nghe thử</button></div><div class="preview-status" id="preview-status-${context}" role="status" aria-live="polite"></div><div id="preview-player-${context}"></div><p class="preview-caption">Nội dung dài tự chia đoạn rồi ghép lại; nên dùng câu ngắn để nghe thử nhanh. Mẫu đã tạo được lưu để nghe lại; lần đầu có thể cần tải mô hình.</p></section>`}
function captureCloneForm(){const f=S.cloneForm;if($('#voice-name'))f.name=$('#voice-name').value;if($('#voice-language'))f.language=$('#voice-language').value;if($('#reference-text'))f.transcript=$('#reference-text').value;if($('#consent'))f.consent=$('#consent').checked;if($('#clone-output-language'))f.outputLanguage=$('#clone-output-language').value}
function invalidatePreview(context){clearTimeout(previewTimers[context]);S.previews[context]={token:++previewSequence};const audio=$(`#preview-player-${context} audio`);audio?.pause?.();paintPreview(context)}
function bindPreview(context){$(`#preview-text-${context}`)?.addEventListener('input',e=>{S.previewTexts[context]=e.target.value;invalidatePreview(context)});paintPreview(context)}
function paintPreview(context){const state=S.previews[context]||{},j=state.job;const status=$(`#preview-status-${context}`),player=$(`#preview-player-${context}`),start=$(`#preview-start-${context}`),cancel=$(`#preview-cancel-${context}`);const pending=state.loading||j&&['queued','running'].includes(j.status);if(start)start.disabled=Boolean(pending&&!state.error);cancel?.classList.toggle('hidden',!j||!['queued','running'].includes(j.status));if(status)status.textContent=state.error|| (state.loading?'Đang chuẩn bị giọng tham chiếu…':j?.status==='queued'?'Đang chờ bộ xử lý · Bạn có thể tiếp tục soạn nội dung.':j?.status==='running'?(j.stage||'Đang tạo câu nghe thử bằng mô hình AI…'):j?.status==='done'?(j.cached?'Đã có mẫu lưu sẵn · Bấm phát để nghe.':'Mẫu đã sẵn sàng · Bấm phát để nghe.'):j?.status==='failed'?'Nghe thử thất bại: '+(j.error||'Kiểm tra cấu hình mô hình.'):j?.status==='cancelled'?'Đã hủy nghe thử.':'');if(player){if(j?.status==='done'&&j.file){if(player.dataset.job!==j.id){player.dataset.job=j.id;player.innerHTML=`<div class="preview-now"><strong>${esc(state.label||'Giọng đang nghe thử')}</strong><audio controls preload="metadata" src="/api/jobs/${j.id}/download"></audio></div>`;const audio=player.querySelector('audio');if(context!=='library'||$('#modal')?.open)audio?.play?.().catch(()=>{})}}else if(player.dataset.job){player.innerHTML='';delete player.dataset.job}}}
async function pollPreview(context,token){if(S.previews[context]?.token!==token)return;try{const job=await api('/previews/'+S.previews[context].job.id);if(S.previews[context]?.token!==token)return;S.previews[context].job=job;paintPreview(context);if(['queued','running'].includes(job.status))previewTimers[context]=setTimeout(()=>pollPreview(context,token),1800)}catch(e){if(S.previews[context]?.token===token){S.previews[context].error=e.message;paintPreview(context)}}}
async function requestPreview(context){if(!requireLocal())return;captureCloneForm();const previous=S.previews[context];if(previous?.error&&previous.job&&['queued','running'].includes(previous.job.status)){previous.error='';paintPreview(context);await pollPreview(context,previous.token);return}if(previous?.loading||previous?.job&&['queued','running'].includes(previous.job.status))return;const token=++previewSequence;clearTimeout(previewTimers[context]);S.previews[context]={token,loading:true};paintPreview(context);try{let payload,label;
 if(context==='clone'){const f={...S.cloneForm},e=S.engines.find(e=>e.id===S.cloneEngine);if(!e?.clone)throw Error('Chọn mô hình hỗ trợ clone.');if(!selectedFile)throw Error('Chọn hoặc thu âm giọng tham chiếu trước.');if(!f.consent)throw Error('Xác nhận quyền sử dụng giọng nói trước khi nghe thử clone.');if(e.id==='gpt-sovits'&&!f.transcript.trim())throw Error('GPT-SoVITS cần lời thoại chính xác trong file giọng mẫu.');const file=selectedFile,signature=JSON.stringify([f.language,f.transcript]);if(!previewReference||previewReference.file!==file||previewReference.signature!==signature){const form=new FormData();form.append('file',file);form.append('transcript',f.transcript);form.append('language',f.language);const ref=await api('/preview-references',{method:'POST',body:form});previewReference={file,signature,id:ref.id}}payload={engine:e.id,preview_ref_id:previewReference.id,language:f.outputLanguage,voice_id:null,preset:'',emotion:S.emotion};label=e.name+' · Giọng clone đang thử';
 }else if(context==='library'){const d={...S.libraryPreview},e=S.engines.find(e=>e.id===d.engine);if(!e)throw Error('Chọn giọng cần nghe thử.');if(d.engine==='vieneu'&&e.config?.variant!==d.variant){const updated=await api('/engines/vieneu',{method:'PUT',body:JSON.stringify({...e.config,variant:d.variant})});Object.assign(e,updated)}payload={engine:d.engine,preset:d.id,language:d.language,voice_id:null,emotion:S.emotion};label=e.name+' · '+d.name;
 }else{payload={engine:S.engine,language:S.language,voice_id:S.voice||null,preset:S.voice?'':S.preset,emotion:S.emotion,auto_emotion:S.autoEmotion};label=engine().name+' · '+(S.voice?S.voices.find(v=>v.id===S.voice)?.name||'Giọng đã lưu':selectedNative()?.name||'Giọng mặc định')}
 const text=($(`#preview-text-${context}`)?.value??S.previewTexts[context]??sampleText(payload.language)).trim();if(!text)throw Error('Nhập nội dung để nghe thử.');if(S.previews[context]?.token!==token)return;const job=await api('/previews',{method:'POST',body:JSON.stringify({...payload,text,speed:context==='studio'?S.speed:1,format:'wav'})});if(S.previews[context]?.token!==token)return;S.previews[context]={token,job,label,loading:false};paintPreview(context);if(job.status==='done'){const audio=$(`#preview-player-${context} audio`);if(audio){audio.currentTime=0;if(context!=='library'||$('#modal')?.open)audio.play().catch(()=>{})}}if(['queued','running'].includes(job.status))previewTimers[context]=setTimeout(()=>pollPreview(context,token),1000)
 }catch(e){if(S.previews[context]?.token===token){S.previews[context]={token,error:e.message};paintPreview(context)}}}
async function cancelPreview(context){const j=S.previews[context]?.job;if(!j)return;const job=await api('/jobs/'+j.id+'/cancel',{method:'POST'});clearTimeout(previewTimers[context]);S.previews[context].job=job;paintPreview(context)}
function appearancePanel(){const t=window.QVTheme.get();return `<div class="field"><label for="theme-mode">Chế độ hiển thị</label><select id="theme-mode" class="select-control"><option value="light" ${t.mode==='light'?'selected':''}>Sáng · Nền trắng, chữ đậm</option><option value="dark" ${t.mode==='dark'?'selected':''}>Tối · Nền xanh đen</option><option value="system" ${t.mode==='system'?'selected':''}>Theo cài đặt hệ thống</option></select></div><label class="label">Chọn màu chủ đạo</label><div class="theme-grid compact">${window.QVTheme.palette.map(p=>`<button class="theme-swatch" data-accent="${p.color}" aria-pressed="${t.accent.toLowerCase()===p.color}"><span class="theme-dot" style="--swatch:${p.color}"></span>${p.name}</button>`).join('')}</div><div class="theme-color-row"><label for="theme-custom">Màu tùy chọn</label><input id="theme-custom" type="color" value="${esc(t.accent)}"><code id="theme-hex">${esc(t.accent)}</code></div><label class="consent"><input id="theme-contrast" type="checkbox" ${t.contrast?'checked':''}>Tương phản cao · Làm rõ khung và đường phân cách</label><div class="field"><label for="theme-scale">Kích thước chữ</label><select id="theme-scale" class="select-control">${[[1,'Tiêu chuẩn · Đã tăng độ rõ'],[1.1,'Lớn hơn · 110%'],[1.2,'Lớn · 120%']].map(([k,v])=>`<option value="${k}" ${t.scale===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="theme-preview"><div class="theme-preview-card"><strong>Nội dung rõ ràng, dễ đọc</strong><small>Màu chữ tự điều chỉnh để giữ độ tương phản.</small></div><button class="button primary" data-action="theme-sample">Nút hành động</button></div><p>Thay đổi áp dụng ngay và tự lưu trong trình duyệt này.</p><button class="text-button" data-action="reset-theme">Khôi phục giao diện mặc định</button>`}
function bindAppearance(){function update(patch){window.QVTheme.set(patch);document.querySelectorAll('[data-accent]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accent.toLowerCase()===window.QVTheme.get().accent.toLowerCase())));if($('#theme-hex'))$('#theme-hex').textContent=window.QVTheme.get().accent;if($('#theme-custom'))$('#theme-custom').value=window.QVTheme.get().accent}$('#theme-mode')?.addEventListener('change',e=>update({mode:e.target.value}));$('#theme-custom')?.addEventListener('input',e=>update({accent:e.target.value}));$('#theme-contrast')?.addEventListener('change',e=>update({contrast:e.target.checked}));$('#theme-scale')?.addEventListener('change',e=>update({scale:Number(e.target.value)}))}
function openAppearance(){modal('Màu sắc & độ dễ đọc',appearancePanel(),'<button class="button primary" data-action="close-modal">Xong · Đã tự lưu</button>');bindAppearance()}
function models(){return `${header('Kho mô hình','Bộ cài tự chuẩn bị mô hình lần lượt. Xem tiến trình và thử lại khi cần.',`<button class="button" data-action="refresh">${icon('refresh')}Kiểm tra lại</button>${S.connected?'<a class="button" href="/api/diagnostics/download" download>Tải chẩn đoán</a>':''}`)}${!S.connected?`<div class="alert">Đây là giao diện web. Hãy tải bản Windows và mở BAT_DAU.bat để cài mô hình và xử lý âm thanh trên máy của bạn. <button class="text-button" data-action="guide">Xem cách cài ${icon('arrow-right')}</button></div>`:''}${setupPanel()}<div class="model-grid">${S.engines.map(e=>`<section class="card model-card"><div class="model-card-top"><span class="model-letter" style="color:${e.color};background:${e.color}15">${e.name.slice(0,1)}</span><span class="tag">${esc(e.tag)}</span></div><h3>${esc(e.name)}</h3><span class="by">${esc(e.by)} · ${e.kind==='asr'?'Speech to Text':e.clone?'TTS + Clone':'TTS · Giọng có sẵn'}</span><p>${esc(e.description)}</p><div class="status-tag ${e.available?'ready':''}"><i class="dot"></i>${statusText(e)}</div>${e.setup?.stage?`<p>${esc(e.setup.stage)}</p>`:''}${e.setup?.error?`<p class="error">${esc(e.setup.error.slice(-350))}</p><button class="text-button" data-engine-error="${e.id}">${icon('help')}Chi tiết lỗi / tải chẩn đoán</button>`:''}<div class="model-card-bottom"><a href="${e.repo}" target="_blank" rel="noopener" class="text-button">Mã nguồn ${icon('external')}</a><button class="button small" data-install="${e.id}" ${['queued','running'].includes(e.setup?.state)?'disabled':''}>${e.setup?.state==='failed'?'Thử lại':'Cài tự động'}</button><button class="button small" data-config="${e.id}">${icon('settings')}Cấu hình</button></div></section>`).join('')}</div>`}
function jobRow(j){const names={queued:'Đang chờ',running:'Đang xử lý',done:'Hoàn tất',failed:'Có lỗi',cancelled:'Đã hủy'};return `<div class="job-row"><div class="job-top"><span class="voice-avatar">${icon(j.type==='asr'?'text':['install','preset_install','setup_engine'].includes(j.type)?'download':'wave')}</span><div><strong>${esc(j.title||'Bản thu mới')}</strong><small>${esc(S.engines.find(e=>e.id===j.engine)?.name||j.engine)} · ${new Date(j.created*1000).toLocaleString('vi-VN')}</small></div><span class="status-pill ${j.status}">${j.status==='running'?'<span class="spinner" style="width:8px;height:8px"></span> ':''}${names[j.status]||j.status}</span></div>${j.status==='done'&&j.type==='tts'?`<audio controls preload="none" src="/api/jobs/${j.id}/download"></audio>`:''}${j.stage?`<p class="job-stage">${esc(j.stage)}</p>`:''}${j.text_result?`<div class="job-text">${esc(j.text_result)}</div>`:''}${j.error?`<div class="error">${esc(j.error)}</div>`:''}<div class="job-actions">${j.status==='done'&&j.file?`<a class="button small" href="/api/jobs/${j.id}/download" download>${icon('download')}${j.type==='asr'?'Tải TXT':'Tải '+(j.format||'WAV').toUpperCase()}</a>${j.type==='tts'?`<a class="button small" href="/api/jobs/${j.id}/download?kind=txt" download>Tải TXT</a>`:''}${['tts','asr'].includes(j.type)?`<button class="button small" data-export-srt="${j.id}">Xuất SRT…</button>`:''}`:''}${['queued','running'].includes(j.status)?`<button class="text-button" data-cancel-job="${j.id}">${icon('stop')}Hủy</button>`:''}${!['install','preset_install','setup_engine'].includes(j.type)&&['failed','cancelled','done'].includes(j.status)?`<button class="text-button" data-retry="${j.id}">${icon('refresh')}Tạo lại</button>`:''}<button class="text-button" data-log="${j.id}">Xem log</button></div></div>`}
function history(){const filtered=S.jobs.filter(j=>(S.filter==='all'||j.status===S.filter)&&(!S.search||[j.title,j.engine].join(' ').toLowerCase().includes(S.search.toLowerCase())));return `${header('Tất cả những lần cất giọng.','Theo dõi quá trình xử lý, nghe lại và tải kết quả.',`<button class="button" data-action="refresh">${icon('refresh')}Làm mới</button>`)}<div class="stat-row"><div class="card stat"><strong>${S.jobs.filter(j=>!['install','preset_install','setup_engine'].includes(j.type)).length}</strong><span>Tác vụ âm thanh</span></div><div class="card stat"><strong>${S.jobs.filter(j=>j.status==='done'&&!['install','preset_install','setup_engine'].includes(j.type)).length}</strong><span>Đã hoàn thành</span></div><div class="card stat"><strong>${S.jobs.filter(j=>['running','queued'].includes(j.status)).length}</strong><span>Đang xử lý / chờ</span></div></div><div class="toolbar"><input class="input-control" id="history-search" value="${esc(S.search)}" placeholder="Tìm theo tên hoặc mô hình…" aria-label="Tìm lịch sử"><select class="select-control" id="history-filter" style="width:170px" aria-label="Lọc trạng thái">${Object.entries({all:'Tất cả trạng thái',done:'Hoàn tất',running:'Đang xử lý',queued:'Đang chờ',failed:'Có lỗi',cancelled:'Đã hủy'}).map(([k,v])=>`<option value="${k}" ${S.filter===k?'selected':''}>${v}</option>`).join('')}</select></div><section id="job-list" class="card">${filtered.length?filtered.map(jobRow).join(''):`<div class="empty-large">${icon('clock')}<h3>${S.jobs.length?'Không tìm thấy tác vụ phù hợp':'Hành trình của bạn bắt đầu ở đây.'}</h3><p>Những tác vụ tạo giọng, chép lời và cài mô hình sẽ xuất hiện tại đây.</p></div>`}</section>`}
function settings(){return `${header('Thiết lập không gian của bạn.','Dữ liệu và cấu hình được lưu trên máy tính khi dùng bản Windows.',`<button class="button" data-action="export-config">${icon('download')}Xuất cấu hình</button>`)}<div class="settings-grid"><section class="card settings-card"><h3>Cập nhật ứng dụng</h3><button type="button" class="button" id="check-studio-updates">Kiểm tra bản cập nhật</button> <a href="https://github.com/taikhoanzaizai-ux/taogiongdoc/releases" target="_blank" rel="noopener noreferrer">GitHub Releases</a><p id="studio-update-status" aria-live="polite"></p></section><section class="card settings-card appearance-section"><h3>Màu sắc & độ dễ đọc</h3>${appearancePanel()}</section><section class="card settings-card"><h3>${icon('monitor')} Phần mềm trên máy</h3><label class="consent"><input id="warm-on-start" type="checkbox" ${S.startPrefs?.warm_on_start!==false?'checked':''}>Tự chuẩn bị model gần nhất khi mở</label><label class="consent"><input id="cached-only" type="checkbox" ${S.startPrefs?.cached_only!==false?'checked':''}>Dùng dữ liệu model đã tải trên máy</label><p>Giọng và model được ghi nhớ. Đổi model sẽ giải phóng model cũ để tiết kiệm RAM. Nếu thiếu tài nguyên, vào Kho mô hình để chuẩn bị khi có Internet.</p><p>Trạng thái: <strong>${S.connected?'Đã kết nối':'Chưa kết nối · đang dùng giao diện web'}</strong></p><p>Địa chỉ ứng dụng Windows:</p><code>${esc(S.status.local_url||"http://127.0.0.1:8765 (tự chọn cổng trống khi cần)")}</code><p>Mở QUAN_VOICE.vbs hoặc biểu tượng QUÂN Voice Studio ngoài Desktop để dùng cửa sổ phần mềm riêng.</p><button class="button primary" data-action="guide">${icon('download')}Tải & cài ứng dụng</button></section><section class="card settings-card"><h3>${icon('folder')} Lưu trữ và bộ nhớ đệm</h3><p>Thư mục dữ liệu:</p><code>${esc(S.status.data_dir||'QuanVoice-Studio\\data (cạnh ứng dụng)')}</code><p>Giọng mẫu, lịch sử, kết quả và trọng số được giữ lại sau khi tắt ứng dụng. Mỗi mô hình chỉ tải những tệp còn thiếu trong lần dùng đầu tiên.</p><p>${S.status.storage?`Còn <strong>${(S.status.storage.free_bytes/2**30).toFixed(1)} GiB</strong> trống trên ổ dữ liệu.`:"Dung lượng trống hiển thị khi mở bản Windows."}</p><p>Mặc định lưu ngay trong <code>data</code> cạnh ứng dụng đã giải nén, cùng ổ với app. Cache tải và tệp tạm cũng dùng ổ này. Bản cập nhật tự chuyển dữ liệu cũ; giữ các liên kết tương thích để môi trường đã cài tiếp tục dùng được. Không di chuyển app khi đang chạy.</p></section><section class="card settings-card"><h3>${icon('text')} Dự án văn bản</h3><p>Giọng đã chọn, cấu hình, giao diện và bản nháp được tự lưu trong dữ liệu ứng dụng khi có kết nối bộ xử lý. Lưu JSON để mang dự án sang máy khác.</p><div class="title-actions"><button class="button" data-action="export-draft">${icon('download')}Lưu dự án</button><button class="button" data-action="import-draft">${icon('upload')}Mở dự án</button></div></section><section class="card settings-card"><h3>${icon('layers')} Các dự án gốc</h3><div class="source-list">${S.engines.map(e=>`<a href="${e.repo}" target="_blank" rel="noopener">${esc(e.name)} ${icon('external')}</a>`).join('')}</div><p>Giữ nguyên giấy phép và thông tin tác giả đi kèm mã nguồn. Xem giấy phép riêng của từng bộ trọng số trước khi phân phối sản phẩm.</p></section></div>`}
function count(){const n=S.text.trim().split(/\s+/).filter(Boolean).length;const el=$('#script-count');if(el)el.textContent=`${S.text.length.toLocaleString('vi-VN')} ký tự · Không giới hạn · Ước tính ~${Math.max(1,Math.round(n/2.6/S.speed))} giây`;}
function setEngine(id){invalidatePreview('studio');S.previewTexts.studio='';const next=S.engines.find(e=>e.id===id);if(!next)return;if(next.kind==='asr'){navigate('transcribe');return}S.engine=id;if(!next.languages.includes(S.language))S.language=next.languages[0];if(!next.clone)S.voice='';S.preset=next.preset||'';ensurePreset();saveDraft();render();}
function navigate(view){if(!labels[view])return;if(view==='voices'&&S.view==='studio'){S.libraryModel=S.engine;S.libraryVariant=engine().config?.variant==='v3nano'?'v3nano':'v3turbo'}if(recorder?.state==='recording')stopRecording();S.view=view;window.location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'});}
function bindView(){
 if(S.view==='studio')bindPreview('studio');if(S.view==='clone'){bindPreview('clone');['voice-name','voice-language','reference-text','consent'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{captureCloneForm();if(id!=='voice-name')invalidatePreview('clone')}));$('#clone-output-language')?.addEventListener('change',()=>{captureCloneForm();S.previewTexts.clone='';invalidatePreview('clone');const input=$('#preview-text-clone');if(input)input.value=sampleText(S.cloneForm.outputLanguage)})}
 bindAppearance();$('#warm-on-start')?.addEventListener('change',e=>{S.startPrefs={...S.startPrefs,warm_on_start:e.target.checked};queuePreferences()});$('#cached-only')?.addEventListener('change',e=>{S.startPrefs={...S.startPrefs,cached_only:e.target.checked};queuePreferences()});$('#library-model')?.addEventListener('change',e=>{S.libraryModel=e.target.value;S.presetSearch='';render()});$('#library-variant')?.addEventListener('change',e=>{S.libraryVariant=e.target.value;render()});$('#preset-search')?.addEventListener('input',e=>{S.presetSearch=e.target.value;$('#builtin-grid').innerHTML=builtInCards(bankFor(S.libraryModel,S.libraryVariant))});
 const script=$('#script');if(script){count();script.addEventListener('input',()=>{S.text=script.value;saveDraft();count()})}
 $('#language')?.addEventListener('change',e=>{S.language=e.target.value;S.previewTexts.studio='';invalidatePreview('studio');ensurePreset();saveDraft();render()});$('#voice')?.addEventListener('change',e=>{invalidatePreview('studio');const v=e.target.value;if(v.startsWith('preset:')){S.voice='';S.preset=v.slice(7)}else{S.voice=v.startsWith('user:')?v.slice(5):'';S.preset=''}saveDraft();render()});$('#preset')?.addEventListener('input',e=>{S.preset=e.target.value;saveDraft()});
 $('#speed')?.addEventListener('input',e=>{S.speed=Number(e.target.value);invalidatePreview('studio');$('#speed-value').textContent=S.speed.toFixed(2)+'×';saveDraft();count()});$('#emotion')?.addEventListener('input',e=>{S.emotion=Number(e.target.value);invalidatePreview('studio');$('#emotion-value').textContent=Math.round(S.emotion*100)+'%';saveDraft()});$('#auto-emotion')?.addEventListener('change',e=>{S.autoEmotion=e.target.checked;invalidatePreview('studio')});
 $('#audio-input')?.addEventListener('change',e=>chooseFile(e.target.files[0]));const zone=$('#upload-zone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragover')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');chooseFile(e.dataTransfer.files[0])});if(selectedFile)showFile()}
 $('#voice-form')?.addEventListener('submit',saveVoice);$('#transcribe-form')?.addEventListener('submit',startTranscribe);$('#history-filter')?.addEventListener('change',e=>{S.filter=e.target.value;render()});$('#history-search')?.addEventListener('input',e=>{S.search=e.target.value;const list=S.jobs.filter(j=>(S.filter==='all'||j.status===S.filter)&&[j.title,j.engine].join(' ').toLowerCase().includes(S.search.toLowerCase()));$('#job-list').innerHTML=list.length?list.map(jobRow).join(''):'<div class="empty-large">Không có kết quả phù hợp</div>'});
}
function chooseFile(file){if(!file)return;if(file.size>100*1024*1024){toast('Tối đa 100 MB mỗi file.');return}selectedFile=file;previewReference=null;invalidatePreview('clone');if(fileURL)URL.revokeObjectURL(fileURL);fileURL=URL.createObjectURL(file);showFile();if($('#voice-name')&&!$('#voice-name').value){$('#voice-name').value=file.name.replace(/\.[^.]+$/,'');S.cloneForm.name=$('#voice-name').value}}
function showFile(){const el=$('#file-detail');if(!el||!selectedFile)return;if(!fileURL)fileURL=URL.createObjectURL(selectedFile);el.innerHTML=`<div class="audio-file-name"><strong>Nghe giọng gốc trước khi clone</strong><br>${esc(selectedFile.name)} · ${(selectedFile.size/1024/1024).toFixed(2)} MB</div><audio id="ref-preview" controls src="${esc(fileURL)}"></audio><canvas class="sample-canvas" id="sample-wave" width="600" height="90" aria-label="Dạng sóng của giọng mẫu"></canvas>`;drawWave(selectedFile).catch(()=>$('#sample-wave')?.remove());}
async function drawWave(file){const ctx=new AudioContext();try{const audio=await ctx.decodeAudioData(await file.arrayBuffer());const canvas=$('#sample-wave');if(!canvas)return;const c=canvas.getContext('2d');c.clearRect(0,0,600,90);const data=audio.getChannelData(0);c.fillStyle='#aa97ce';for(let i=0;i<180;i++){let peak=0;const start=Math.floor(i*data.length/180),end=Math.floor((i+1)*data.length/180);for(let k=start;k<end;k+=Math.max(1,Math.floor((end-start)/100)))peak=Math.max(peak,Math.abs(data[k]));let h=Math.max(2,peak*75);c.fillRect(i*600/180,45-h/2,2,h)}}finally{await ctx.close()}}
async function record(){if(recorder?.state==='recording'){stopRecording();return}if(!navigator.mediaDevices?.getUserMedia){toast('Trình duyệt này chưa hỗ trợ thu âm. Hãy chọn file từ máy.');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(recordStream);const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const type=recorder.mimeType;chooseFile(new File(chunks,'Giong-thu-'+Date.now()+(type.includes('mp4')?'.m4a':'.webm'),{type}));recordStream?.getTracks().forEach(t=>t.stop())};recorder.start();const button=$('[data-action="record"]');button?.classList.add('recording');if(button)button.innerHTML=icon('stop')+' Dừng thu âm';let seconds=0;recordTimer=setInterval(()=>{seconds++;if($('#record-time'))$('#record-time').textContent=seconds+' giây / tối đa 60 giây';if(seconds>=60)stopRecording()},1000)}catch(err){recordStream?.getTracks().forEach(t=>t.stop());toast('Không truy cập được micro. Kiểm tra quyền thu âm hoặc chọn file.')}}
function stopRecording(){clearInterval(recordTimer);if(recorder?.state==='recording')recorder.stop();const button=$('[data-action="record"]');button?.classList.remove('recording');if(button)button.innerHTML=icon('mic')+' Thu âm trực tiếp';if($('#record-time'))$('#record-time').textContent='Đã dừng thu âm';}
async function saveVoice(event){event.preventDefault();if(!requireLocal())return;if(!selectedFile){toast('Chọn hoặc thu âm một giọng mẫu trước.');return}captureCloneForm();const button=event.submitter;button.disabled=true;try{const form=new FormData();form.append('file',selectedFile);form.append('name',$('#voice-name').value);form.append('language',$('#voice-language').value);form.append('transcript',$('#reference-text').value);form.append('preferred_engine',S.cloneEngine);const outputLanguage=S.cloneForm.outputLanguage;const v=await api('/voices',{method:'POST',body:form});S.voices.unshift(v);S.engine=v.preferred_engine||S.cloneEngine;S.voice=v.id;S.preset='';S.language=outputLanguage;invalidatePreview('studio');selectedFile=null;if(fileURL)URL.revokeObjectURL(fileURL);fileURL=null;saveDraft();navigate('studio');toast('Đã lưu giọng mẫu. Nhập nội dung để tạo giọng clone.')}catch(e){toast(e.message)}finally{button.disabled=false}}
function requireLocal(){if(S.connected)return true;guide('Để tạo âm thanh thật, hãy mở bản Windows trên máy tính.');return false}
async function generate(retry){if(busy)return;if(!requireLocal())return;if(!S.text.trim()&&!retry){toast('Nhập nội dung cần tạo giọng.');$('#script')?.focus();return}if(!retry&&!engine().available){configModal(S.engine);toast('Cài đặt hoặc cấu hình mô hình trước khi tạo giọng.');return}busy=true;const button=$('[data-action="generate"]');if(button)button.disabled=true;try{const body=retry||{engine:S.engine,text:S.text,language:S.language,voice_id:S.voice||null,preset:S.preset,speed:S.speed,format:S.format,emotion:S.emotion,auto_emotion:S.autoEmotion,title:S.text.trim().slice(0,55)};const texts=!retry&&S.batch?S.text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean):[body.text];for(let i=0;i<texts.length;i++){const j=await api('/jobs',{method:'POST',body:JSON.stringify({...body,text:texts[i],title:texts.length>1?`Đoạn ${i+1} · ${texts[i].slice(0,40)}`:body.title})});S.jobs.unshift(j)}toast(`Đã thêm ${texts.length} tác vụ vào hàng đợi.`);if(S.view==='studio')$('#recent-result').innerHTML=resultPanel();else render()}catch(e){toast(e.message)}finally{busy=false;if(button)button.disabled=false}}
async function startTranscribe(event){event.preventDefault();if(!requireLocal())return;const button=event.submitter;button.disabled=true;try{const file=$('#source-file').files[0];let id=$('#source-existing')?.value;if(file){const form=new FormData();form.append('file',file);form.append('name',file.name);form.append('kind','source');form.append('language',$('#asr-lang').value);const v=await api('/voices',{method:'POST',body:form});S.voices.unshift(v);id=v.id}if(!id)throw new Error('Hãy chọn một file âm thanh.');const j=await api('/jobs',{method:'POST',body:JSON.stringify({engine:'whisper',voice_id:id,language:$('#asr-lang').value,title:'Chép lời · '+(file?.name||'Âm thanh đã lưu')})});S.jobs.unshift(j);render();toast('Đã thêm tác vụ chép lời vào hàng đợi.')}catch(e){toast(e.message)}finally{button.disabled=false}}
function modal(title,body,footer=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function guide(message=''){modal('Cài tự động trên Windows',`${message?`<div class="alert">${esc(message)}</div>`:''}<p>Tải gói đầy đủ trong cuộc trò chuyện và giải nén vào thư mục riêng, ví dụ D:\\QuanVoice.</p><div class="help-step"><span class="step-number">1</span><div><strong>Mở BAT_DAU.bat</strong><p>Bộ cài tự chuẩn bị Python 3.11 x64, Python Launcher, PATH, Git và FFmpeg. Bạn không cần cài từng công cụ bằng tay.</p></div></div><div class="help-step"><span class="step-number">2</span><div><strong>Giữ kết nối Internet và chờ mô hình</strong><p>Studio tự mở tại cổng cục bộ còn trống; địa chỉ thực tế hiển thị trong Cài đặt. Kho mô hình hiển thị tiến trình từng mô hình. Trọng số AI có thể cần nhiều GB và thời gian tải dài. Nếu Windows yêu cầu khởi động lại để bật WSL cho Fish, hãy khởi động lại rồi mở BAT_DAU.bat.</p></div></div><p>Muốn bắt đầu nhẹ hơn: mở BAT_DAU_NHANH.bat để tự cài VieNeu và Whisper trước. GPT-SoVITS / Fish tự khởi động API khi dùng. Nút tải bên dưới là bộ cài nhỏ: công cụ và mã nguồn được tải thêm; gói đầy đủ đã kèm chúng.</p>`,`<button class="button" data-action="close-modal">Đã hiểu</button>${S.connected?'':`<a class="button primary" href="QuanVoice-Windows.zip" download>${icon('download')}Tải bộ cài nhỏ</a>`}`)}
function setupPanel(){if(!S.connected)return '';const ready=S.engines.filter(e=>e.setup?.state==='ready').length;const active=S.engines.filter(e=>['queued','running'].includes(e.setup?.state)).length;return `<section class="card setup-panel"><strong>Chuẩn bị tự động · ${ready}/7 mô hình</strong><p>${active?`${active} mô hình đang cài hoặc chờ. Bạn có thể dùng mô hình đã xong; xem log ở Lịch sử & hàng đợi.`:'Có thể thử lại phần cài chưa xong. Đóng cửa sổ ứng dụng sẽ dừng tiến trình đang chạy.'}</p><progress max="7" value="${ready}" aria-label="Số mô hình đã chuẩn bị"></progress><div><button class="button primary" data-action="setup-all" ${active?'disabled':''}>${icon('download')}Cài tiếp toàn bộ</button> <button class="button" data-view="history">Xem tiến trình và log</button></div><small>Trọng số cần Internet lần đầu. Fish Speech cần WSL2; Windows có thể yêu cầu khởi động lại.</small></section>`}

function configModal(id){const e=S.engines.find(x=>x.id===id);const c=e.config||{};modal('Cấu hình '+esc(e.name),`<div class="alert">${esc(e.note)}</div><p>${esc(statusText(e))}. Cài mô hình có thể tải nhiều GB dữ liệu. Thư viện và trọng số được lưu lại cho các lần sau.</p><form id="config-form" data-engine-id="${id}"><div class="field"><label for="cfg-python">Đường dẫn Python riêng của mô hình</label><input class="input-control" id="cfg-python" value="${esc(c.python||'')}" placeholder="Cài mô hình để tự thiết lập"></div><div class="field"><label for="cfg-repo">Thư mục mã nguồn</label><input class="input-control" id="cfg-repo" value="${esc(c.repo||'')}" placeholder="Cài mô hình để tự thiết lập"></div><div class="field"><label for="cfg-checkpoint">Thư mục trọng số / mã model Hugging Face</label><input class="input-control" id="cfg-checkpoint" value="${esc(c.checkpoint||'')}" placeholder="${id==='vibevoice'?'microsoft/VibeVoice-Realtime-0.5B':'Đường dẫn thư mục checkpoint (nếu cần)'}"></div><div class="field"><label for="cfg-device">Thiết bị xử lý</label><select class="select-control" id="cfg-device"><option value="cpu" ${c.device==='cpu'?'selected':''}>CPU</option><option value="cuda" ${c.device==='cuda'?'selected':''}>NVIDIA GPU · CUDA (cần PyTorch tương thích)</option></select></div><div class="field"><label for="cfg-variant">${id==='whisper'?'Kích thước Whisper':id==='vieneu'?'Phiên bản VieNeu':'Phiên bản tích hợp'}</label>${id==='whisper'?`<select id="cfg-variant" class="select-control">${['tiny','base','small','medium','large','turbo'].map(v=>`<option ${c.variant===v?'selected':''}>${v}</option>`).join('')}</select>`:id==='vieneu'?`<select id="cfg-variant" class="select-control"><option value="v3turbo">v3 Turbo · Khuyến nghị</option><option value="v3nano" ${c.variant==='v3nano'?'selected':''}>v3 Nano · CPU yếu</option></select>`:`<input id="cfg-variant" class="input-control" readonly value="${id==='index-tts'?'2.5':id==='chatterbox'?'Multilingual':id==='vibevoice'?'Realtime 0.5B':'API chính thức'}">`}</div>${['gpt-sovits','fish-speech'].includes(id)?`<div class="field"><label for="cfg-endpoint">API chạy trên cùng máy</label><input id="cfg-endpoint" class="input-control" value="${esc(c.endpoint||('http://127.0.0.1:'+(id==='gpt-sovits'?'9880':'8080')))}"></div><p>${id==='gpt-sovits'?'API tự khởi động khi sử dụng sau khi chuẩn bị xong. Nếu lỗi, dùng Chi tiết lỗi để xem nhật ký.':'Bộ cài chuẩn bị Fish trong WSL2 riêng và tự mở API khi dùng. Xem Chi tiết lỗi nếu chưa cài xong.'}</p>`:''}</form><p><a href="${e.repo}" target="_blank" rel="noopener">Tài liệu và giấy phép của dự án ${icon('external')}</a></p>`,`<button class="button" data-install="${id}">${icon('download')}Cài mô hình</button><button class="button primary" data-save-config="${id}">Lưu cấu hình</button>`)}
function pickEngine(){modal('Đủ 7 mô hình · 6 tạo giọng, 1 chép lời',`<p>Chọn mô hình tạo giọng bên dưới. Whisper chuyển âm thanh thành chữ, không có chức năng tạo/clone giọng.</p><div class="modal-models">${S.engines.map(e=>`<section class="model-picker-item"><button class="modal-model ${S.engine===e.id?'selected':''}" data-pick-engine="${e.id}"><span class="model-letter" style="color:${e.color};background:${e.color}15">${e.name.slice(0,1)}</span><div><strong>${esc(e.name)}${e.kind==='asr'?' · Chép lời':''}</strong><small>${e.kind==='asr'?'Mở Âm thanh → văn bản':statusText(e)}</small><small>${e.languages.length} lựa chọn ngôn ngữ: ${esc(e.languages.map(l=>languageNames[l]||l.toUpperCase()).join(' · '))}</small></div></button>${e.setup?.state==='failed'?`<div class="picker-error-actions"><button class="text-button" data-engine-error="${e.id}">${icon('help')}Chi tiết lỗi</button><button class="button small" data-install="${e.id}">Thử lại</button></div>`:''}</section>`).join('')}</div><p>Số ngôn ngữ tùy model. VieNeu và Fish có tiếng Việt trong danh sách tích hợp; việc nạp được model phụ thuộc cài đặt trên máy.</p>`)}
async function showEngineError(id){if(!requireLocal())return;const d=await api('/engines/'+id+'/diagnostics');modal('Lỗi cài '+esc(d.name),`<div class="alert"><strong>${esc(d.summary)}</strong><p>${esc(d.hint)}</p></div><p>Đang lưu dữ liệu tại: <code>${esc(S.status.data_dir||"data cạnh app")}</code>${S.status.storage?` · Còn ${(S.status.storage.free_bytes/2**30).toFixed(1)} GiB`:""}</p><pre>${esc(d.log)}</pre>`,`<a class="button" href="/api/diagnostics/download" download>${icon('download')}Tải chẩn đoán</a><button class="button primary" data-install="${id}">Thử lại mô hình này</button>`)}

function exportTime(ms){const total=Math.max(0,ms)/1000;return `${Math.floor(total/60)}:${(total%60).toFixed(3).padStart(6,'0')}`}
async function setSrtSource(e,id){
 const manifest=id==='draft'?window.QVSubtitles.draft(e.draftText,e.seconds):await api('/jobs/'+encodeURIComponent(id)+'/exports');
 e.id=id;e.manifest=manifest;e.selected=new Set(manifest.parts.map(p=>p.id));
}
async function openSrtExport(id){
 const choices=S.connected?S.jobs.filter(j=>j.status==='done'&&['tts','asr'].includes(j.type)):[];
 if(id&&!choices.some(j=>j.id===id))choices.unshift({id,title:'Bản thu đã chọn'});
 if(!id)id=choices.find(j=>j.type==='tts'&&j.text===S.text)?.id||(S.text.trim()?'draft':choices[0]?.id);
 if(!id){toast('Nhập văn bản hoặc tạo bản thu trước khi xuất SRT.');return}
 if(id!=='draft'&&!requireLocal())return;
 const e={choices,draftText:S.text,seconds:Math.max(1,Math.ceil(S.text.trim().split(/\s+/).length/2.5/(S.speed||1))),scope:'full',timeline:'local'};
 await setSrtSource(e,id);S.exportDialog=e;renderSrtExport();
}
function renderSrtExport(){
 const e=S.exportDialog;if(!e)return;const partial=e.scope==='parts';
 modal('Xuất phụ đề SRT',`
 <div class="field"><label for="srt-source">Nguồn phụ đề</label><select id="srt-source" class="select-control">
 ${e.draftText?.trim()?`<option value="draft" ${e.id==='draft'?'selected':''}>Văn bản đang soạn · mốc thời gian ước lượng</option>`:''}
 ${(e.choices||[{id:e.id,title:e.manifest.title}]).map(j=>`<option value="${esc(j.id)}" ${e.id===j.id?'selected':''}>Bản thu: ${esc(j.title||j.id)}</option>`).join('')}</select></div>
 ${e.id==='draft'?`<div class="field"><label for="srt-duration">Tổng thời lượng dự kiến (giây)</label><input id="srt-duration" class="input-control" type="number" min="0.001" step="any" value="${e.seconds}"><small class="export-duration-help">Ước tính ban đầu theo tốc độ đọc. Bạn có thể nhập thời lượng mong muốn.</small></div>`:''}
 <div class="field"><label for="srt-scope">Nội dung xuất</label><select id="srt-scope" class="select-control"><option value="full" ${!partial?'selected':''}>Toàn bộ · một file SRT đầy đủ</option><option value="parts" ${partial?'selected':''}>Từng đoạn · chọn một hoặc nhiều đoạn</option></select></div>
 <p class="export-note">${esc(e.manifest.timing_note)}</p>
 ${partial?`<div class="field"><label for="srt-timeline">Mốc thời gian của mỗi file</label><select id="srt-timeline" class="select-control"><option value="local" ${e.timeline==='local'?'selected':''}>Bắt đầu từ 00:00:00 · dùng với clip riêng</option><option value="global" ${e.timeline==='global'?'selected':''}>Giữ mốc trong bản đầy đủ</option></select></div>
 <label class="consent"><input id="srt-select-all" type="checkbox" ${e.selected.size===e.manifest.parts.length?'checked':''}>Chọn tất cả ${e.manifest.parts.length} đoạn</label>
 <div class="export-parts">${e.manifest.parts.map(p=>`<label class="export-part"><input type="checkbox" data-srt-part="${p.id}" ${e.selected.has(p.id)?'checked':''}><span><strong>Đoạn ${p.id}</strong><small>${exportTime(p.start_ms)} → ${exportTime(p.end_ms)} · ${p.characters.toLocaleString('vi-VN')} ký tự</small><span>${esc(p.text.slice(0,200))}${p.characters>200?'…':''}</span></span></label>`).join('')}</div>
 <p>Một đoạn tải thành SRT riêng; nhiều đoạn được gom thành ZIP. Mỗi file đánh số phụ đề lại từ 1.</p>`:`<p>Gộp ${e.manifest.parts.length} đoạn theo đúng thứ tự. Các đoạn văn cách nhau bằng dòng trống.</p>`}`,
 `<button class="button" data-action="close-modal">Đóng</button><button class="button primary" id="download-srt-export">${icon('download')}Tải ${partial?'các đoạn đã chọn':'SRT đầy đủ'}</button>`);
 $('#srt-source').onchange=async event=>{const previous=e.id;event.target.disabled=true;try{await setSrtSource(e,event.target.value);renderSrtExport()}catch(error){event.target.value=previous;event.target.disabled=false;toast(error.message)}};
 if(e.id==='draft')$('#srt-duration').onchange=event=>{e.seconds=Number(event.target.value);try{e.manifest=window.QVSubtitles.draft(e.draftText,e.seconds);renderSrtExport()}catch(error){toast(error.message)}};
 $('#srt-scope').onchange=event=>{e.scope=event.target.value;renderSrtExport()};
 if(partial){
  $('#srt-timeline').onchange=event=>{e.timeline=event.target.value};
  $('#srt-select-all').onchange=event=>{e.selected=new Set(event.target.checked?e.manifest.parts.map(p=>p.id):[]);renderSrtExport()};
  document.querySelectorAll('[data-srt-part]').forEach(box=>box.onchange=()=>{const id=Number(box.dataset.srtPart);if(box.checked)e.selected.add(id);else e.selected.delete(id);$('#srt-select-all').checked=e.selected.size===e.manifest.parts.length});
 }
 $('#download-srt-export').onclick=async event=>{
  const button=event.currentTarget;button.disabled=true;
  try{
   if(partial&&!e.selected.size)throw new Error('Chọn ít nhất một đoạn để tải.');
   if(e.id==='draft'){
    e.seconds=Number($('#srt-duration').value);e.manifest=window.QVSubtitles.draft(e.draftText,e.seconds);
    const file=window.QVSubtitles.download(e.manifest,e.scope,e.selected,e.timeline);downloadBlob(file.name,file.content,file.type);toast('Đã xuất '+file.name);return;
   }
   const response=await fetch('/api/jobs/'+encodeURIComponent(e.id)+'/exports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({format:'srt',scope:e.scope,parts:partial?[...e.selected]:null,timeline:e.timeline})});
   if(!response.ok){const error=await response.json();throw new Error(typeof error.detail==='string'?error.detail:'Không xuất được phụ đề.')}
   const header=response.headers.get('Content-Disposition')||'',match=header.match(/filename\*=UTF-8''([^;]+)/i),name=match?decodeURIComponent(match[1]):'QuanVoice.srt';
   const blob=await response.blob();downloadBlob(name,blob,blob.type);toast('Đã xuất '+name);
  }catch(error){toast(error.message)}finally{button.disabled=false}
 };
}
function downloadBlob(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function pickFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',async()=>{if(input.files[0])try{await callback(input.files[0])}catch(e){toast(e.message)}});input.click()}
async function sync(initial=false){try{const status=await api('/status',{signal:AbortSignal.timeout(20000)});S.status=status;S.connected=true;S.engines=status.engines;const configKey=JSON.stringify(status.engines.map(e=>e.config));if(initial||S.configKey!==configKey){S.banks=await api('/presets');S.configKey=configKey;ensurePreset()}const [voices,jobs]=await Promise.all([api('/voices'),api('/jobs')]);const jobsChanged=JSON.stringify(jobs)!==JSON.stringify(S.jobs);S.voices=voices;S.jobs=jobs;if(!S.prefsLoaded)await restorePreferences();document.documentElement.dataset.desktop=status.desktop_mode?'1':'0';if($('#desktop-exit'))$('#desktop-exit').classList.toggle('hidden',!status.desktop_mode);if($('#runtime-status'))$('#runtime-status').innerHTML=runtimePanel();$('#connection').classList.add('online');$('#connection').innerHTML='<i></i>Bộ xử lý cục bộ đã kết nối';if(initial||S.view==='models')render();else if(jobsChanged&&['history','transcribe'].includes(S.view))render();else if(jobsChanged&&S.view==='studio'&&$('#recent-result'))$('#recent-result').innerHTML=resultPanel()}catch{S.connected=false;$('#connection').classList.remove('online');$('#connection').innerHTML='<i></i>Bản web · chưa có bộ xử lý';if(initial)render()}}
function inlineConfirm(title,body,action){modal(title,`<p>${esc(body)}</p>`,`<button class="button" data-action="close-modal">Giữ lại</button><button class="button danger" id="confirm-action">Xóa giọng</button>`);$('#confirm-action').onclick=async()=>{try{await action();$('#modal').close()}catch(e){toast(e.message)}}}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;try{
 if(b.dataset.exportSrt){await openSrtExport(b.dataset.exportSrt);return}
 if(b.dataset.engineError){await showEngineError(b.dataset.engineError);return}
 if(b.dataset.cloneEngine){captureCloneForm();const m=S.engines.find(e=>e.id===b.dataset.cloneEngine);if(!m?.clone)return;S.cloneEngine=m.id;if(!m.languages.includes(S.cloneForm.outputLanguage)){S.cloneForm.outputLanguage=m.languages[0];S.previewTexts.clone=''}invalidatePreview('clone');saveDraft();render();return}if(b.dataset.previewContext){await requestPreview(b.dataset.previewContext);return}if(b.dataset.cancelPreview){await cancelPreview(b.dataset.cancelPreview);return}
 if(b.dataset.accent){window.QVTheme.set({accent:b.dataset.accent});document.querySelectorAll('[data-accent]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if($('#theme-custom'))$('#theme-custom').value=b.dataset.accent;if($('#theme-hex'))$('#theme-hex').textContent=b.dataset.accent;return}if(b.dataset.libraryTab){S.libraryTab=b.dataset.libraryTab;render();return}if(b.dataset.native){await chooseNative(b.dataset.native,b.dataset.nativeEngine,b.dataset.nativeVariant);return}if(b.dataset.previewNative){await previewNative(b.dataset.previewNative,b.dataset.nativeEngine,b.dataset.nativeVariant);return}
 if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.engine){setEngine(b.dataset.engine);return}if(b.dataset.pickEngine){setEngine(b.dataset.pickEngine);$('#modal').close();return}if(b.dataset.config){configModal(b.dataset.config);return}
 if(b.dataset.mode){S.batch=b.dataset.mode==='batch';render();return}if(b.dataset.format){S.format=b.dataset.format;saveDraft();render();return}if(b.dataset.template){S.text=templates[b.dataset.template];saveDraft();render();return}
 if(b.dataset.useVoice){invalidatePreview('studio');S.voice=b.dataset.useVoice;const chosen=S.voices.find(v=>v.id===S.voice);S.engine=S.engines.some(e=>e.id===chosen?.preferred_engine&&e.clone)?chosen.preferred_engine:engine().clone?S.engine:'vieneu';if(!engine().languages.includes(S.language))S.language=engine().languages[0];saveDraft();navigate('studio');return}
 if(b.dataset.deleteVoice){const v=S.voices.find(v=>v.id===b.dataset.deleteVoice);inlineConfirm('Xóa giọng mẫu?',`Giọng “${v.name}” sẽ được xóa khỏi máy tính.`,async()=>{await api('/voices/'+v.id,{method:'DELETE'});S.voices=S.voices.filter(x=>x.id!==v.id);if(S.voice===v.id)S.voice='';saveDraft();render();toast('Đã xóa giọng mẫu.')});return}
 if(b.dataset.install){if(!requireLocal())return;b.disabled=true;try{const r=await api('/setup/engine/'+b.dataset.install,{method:'POST'});S.jobs.unshift(...r.scheduled);$('#modal').close();navigate('history');toast('Đã đưa cài đặt vào hàng đợi. Mở log để theo dõi.')}finally{b.disabled=false}return}
 if(b.dataset.saveConfig){if(!requireLocal())return;const c={python:$('#cfg-python').value,repo:$('#cfg-repo').value,checkpoint:$('#cfg-checkpoint').value,device:$('#cfg-device').value,variant:$('#cfg-variant').value,endpoint:$('#cfg-endpoint')?.value||''};await api('/engines/'+b.dataset.saveConfig,{method:'PUT',body:JSON.stringify(c)});$('#modal').close();await sync();render();toast('Đã lưu cấu hình.');return}
 if(b.dataset.cancelJob){await api('/jobs/'+b.dataset.cancelJob+'/cancel',{method:'POST'});await sync();return}if(b.dataset.log){const r=await api('/jobs/'+b.dataset.log+'/log');modal('Nhật ký xử lý',`<pre>${esc(r.text)}</pre>`);return}if(b.dataset.retry){const j=S.jobs.find(x=>x.id===b.dataset.retry);await generate({engine:j.engine,text:j.text,language:j.language,voice_id:j.voice_id,preset:j.preset,speed:j.speed,format:j.format,emotion:j.emotion,auto_emotion:j.auto_emotion,title:j.title});return}
 switch(b.dataset.action){case 'setup-all':if(requireLocal()){const r=await api('/setup/start',{method:'POST',body:JSON.stringify({profile:'all'})});S.jobs.unshift(...r.scheduled);await sync();toast(r.scheduled.length?'Đã tiếp tục chuẩn bị các mô hình.':'Các mô hình mặc định đã được chuẩn bị.')}break;case 'warm-current':if(requireLocal()){await api('/runtime/warm',{method:'POST',body:JSON.stringify({engine:S.engine})});toast('Đang chuẩn bị model từ dữ liệu đã lưu.');await sync()}break;case 'release-runtime':await api('/runtime/release',{method:'POST'});await sync();break;case 'desktop-exit':if(confirm('Đóng Studio và dừng các tác vụ đang chạy?'))await api('/app/exit',{method:'POST'});break;case 'appearance':openAppearance();break;case 'theme-sample':toast('Màu và kích thước mới đã được áp dụng.');break;case 'reset-theme':window.QVTheme.reset();if($('#modal').open)openAppearance();else render();toast('Đã khôi phục giao diện mặc định.');break;case 'refresh-presets':await refreshPresets();break;case 'preview-current':await requestPreview('studio');break;case 'download-vibe-presets':if(requireLocal()){const j=await api('/presets/vibevoice/download',{method:'POST'});S.jobs.unshift(j);navigate('history');toast('Đã thêm tải gói giọng chính thức vào hàng đợi.')}break;case 'guide':guide();break;case 'close-modal':$('#modal').close();break;case 'pick-engine':pickEngine();break;case 'generate':await generate();break;case 'refresh':await sync(true);toast(S.connected?'Đã cập nhật trạng thái.':'Mở bản Windows để kết nối bộ xử lý.');break;case 'record':await record();break;case 'clear-text':S.text='';saveDraft();render();$('#script')?.focus();break;case 'normalize-text':S.text=S.text.replace(/[\t ]+/g,' ').replace(/ *\n */g,'\n').replace(/\n{3,}/g,'\n\n').trim();saveDraft();render();toast('Đã chuẩn hóa khoảng trắng.');break;case 'export-srt':await openSrtExport();break;case 'export-txt':if(!S.text.trim()){toast('Chưa có văn bản để xuất.');break}downloadBlob('QuanVoice-VanBan.txt',S.text,'text/plain;charset=utf-8');toast('Đã xuất toàn bộ văn bản TXT.');break;case 'export-draft':downloadBlob('QuanVoice-DuAn.json',JSON.stringify({version:1,...JSON.parse(localStorage.getItem('qv-draft')||'{}'),text:S.text,engine:S.engine,language:S.language},null,2));toast('Đã xuất dự án văn bản. Giọng mẫu lưu riêng trên máy.');break;case 'import-draft':pickFile('.json',async f=>{const d=JSON.parse(await f.text());if(typeof d.text!=='string'||!S.engines.some(e=>e.id===d.engine&&e.kind==='tts'))throw new Error('Tệp dự án không hợp lệ.');const e=S.engines.find(e=>e.id===d.engine);S.text=d.text;S.engine=d.engine;S.language=e.languages.includes(d.language)?d.language:e.languages[0];S.preset=typeof d.preset==='string'?d.preset:e.preset||'';S.voice=S.voices.some(v=>v.id===d.voice)?d.voice:'';S.speed=Math.max(.5,Math.min(2,Number(d.speed)||1));S.format=d.format==='mp3'?'mp3':'wav';S.emotion=Math.max(0,Math.min(1,Number(d.emotion)||.5));saveDraft();navigate('studio');toast('Đã mở dự án.');});break;case 'import-text':pickFile('.txt,text/plain',async f=>{S.text=await f.text();saveDraft();render();toast('Đã nhập văn bản.');});break;case 'export-config':if(requireLocal()){const c=await api('/settings/export');downloadBlob('QuanVoice-CauHinh.json',JSON.stringify(c,null,2))}break;}
 }catch(e){toast(e.message||'Có lỗi xảy ra. Hãy thử lại.')}});
$('#modal').addEventListener('close',()=>$('#modal').querySelectorAll('audio').forEach(a=>a.pause()));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
window.addEventListener('beforeunload',()=>{recordStream?.getTracks().forEach(t=>t.stop());saveDraft();if(S.connected&&S.prefsLoaded&&typeof fetch==='function')fetch('/api/preferences',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify(preferenceSnapshot(false))}).catch(()=>{})});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(labels[view]&&S.view!==view){S.view=view;render()}});
(async()=>{try{S.engines=await (await fetch('engines.json')).json();if(['v3turbo','v3nano'].includes(draft.vieneuVariant))S.engines.find(e=>e.id==='vieneu').config={variant:draft.vieneuVariant};S.banks=await (await fetch('presets.json')).json();if(!S.engines.some(e=>e.id===S.engine&&e.kind==='tts'))S.engine='vieneu';if(!engine().languages.includes(S.language))S.language=engine().languages[0];if(labels[location.hash.slice(1)])S.view=location.hash.slice(1);hydrate();render();await sync(true);setInterval(()=>{if(S.connected&&!document.hidden)sync()},7000)}catch(e){$('#main-content').innerHTML='<div class="alert">Không tải được danh sách mô hình. Hãy tải lại trang.</div>';console.error(e)}})();

document.addEventListener('click', async (event) => {
  const button = event.target.closest('#check-studio-updates');
  if (!button) return;
  const status = document.getElementById('studio-update-status');
  button.disabled = true;
  status.textContent = 'Đang kiểm tra GitHub…';
  try {
    const response = await fetch('/api/updates');
    if (!response.ok) throw new Error('update check failed');
    const release = await response.json();
    if (!release.available) {
      status.textContent = 'Chưa có bản mới hơn ' + release.current + '.';
      return;
    }
    const link = document.createElement('a');
    link.href = release.download;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = 'Tải bản ' + release.latest;
    status.replaceChildren(link, ' · Đóng Studio, giải nén đè các tệp ứng dụng, rồi mở lại.');
  } catch {
    status.textContent = 'Không kiểm tra được GitHub. Hãy thử lại.';
  } finally {
    button.disabled = false;
  }
});
